payload.ingredientsText:
64 % apfelfüllung [83 % apfelzubereitung (98 % äpfel, speisesalz, säuerungsmittel: citronensäure; antioxidationsmittel: ascorbinsäure), 6,4 % apfelmus (93 % äpfel, zucker, antioxidationsmittel: ascorbinsäure), 2,9 % sultaninen, zucker, modifizierte stärke, natürliches aroma, jodiertes speisesalz (speisesalz, kaliumjodat), zimt],

25 % mürbeteig {weizenmehl, zucker, margarine [pflanzliche fette (palm, kokos), wasser, rapsöl, emulgator: mono - und diglyceride von speisefettsäuren, lecithine; säuerungsmittel: citronensäure], hühnervollei, backtriebmittel: natriumcarbonate, natriumcitrate; jodiertes speisesalz (speisesalz, kaliumjodat)},

11 % streusel {weizenmehl, zucker, margarine [pflanzliche fette (palm, kokos), wasser, rapsöl, emulgator: mono - und diglyceride von speisefettsäuren, lecithine; säuerungsmittel: citronensäure], natürliches aroma (enthält milch), jodiertes speisesalz (speisesalz, kaliumjodat), zimt}
